/**
 * Describes last games export file,
 * generated by command "pnpm hex export-games" in "assets/export-data/manifest.json".
 */
export type ExportGamesDataManifest = {
    description: string;

    /**
     * Public path of the file, e.g "/export-data/playhex-games-2026-01-01.json.gz"
     */
    filename: string;

    /**
     * ISO date
     */
    generated_at: string;

    filesize: number;
    filesizeUnzipped: number;
    itemsCount: number;
};
